public static String testableHtml(PageData pageData, boolean includeSuiteSetup) throws Exception {
    String content = PageContentBuilder.buildPageContent(pageData, includeSuiteSetup);
    pageData.setContent(content);
    return pageData.getHTML();
}

class PageContentBuilder {
    public static String buildPageContent(PageData pageData, boolean includeSuiteSetup) {
        StringBuffer buffer = new StringBuffer();
        if (pageData.hasAttribute("Test")) {
            buffer.append(handleSetupPages(pageData, includeSuiteSetup));
        }
        buffer.append(pageData.getContent());
        if (pageData.hasAttribute("Test")) {
            buffer.append(handleTeardownPages(pageData, includeSuiteSetup));
        }
        return buffer.toString();
    }

    private static String handleSetupPages(PageData pageData, boolean includeSuiteSetup) {
        StringBuffer setupBuffer = new StringBuffer();
        WikiPage wikiPage = pageData.getWikiPage();
        if (includeSuiteSetup) {
            setupBuffer.append(getSetupContent(wikiPage, SuiteResponder.SUITE_SETUP_NAME));
        }
        setupBuffer.append(getSetupContent(wikiPage, "SetUp"));
        return setupBuffer.toString();
    }

    private static String handleTeardownPages(PageData pageData, boolean includeSuiteSetup) {
        StringBuffer teardownBuffer = new StringBuffer();
        WikiPage wikiPage = pageData.getWikiPage();
        teardownBuffer.append(getTeardownContent(wikiPage, "TearDown"));
        if (includeSuiteSetup) {
            teardownBuffer.append(getTeardownContent(wikiPage, SuiteResponder.SUITE_TEARDOWN_NAME));
        }
        return teardownBuffer.toString();
    }

    private static String getSetupContent(WikiPage page, String type) {
        WikiPage setupPage = PageCrawlerImpl.getInheritedPage(type, page);
        if (setupPage == null) {
            return "";
        }
        WikiPagePath path = setupPage.getPageCrawler().getFullPath(setupPage);
        return "! include -setup ." + PathParser.render(path) + "\n";
    }

    private static String getTeardownContent(WikiPage page, String type) {
        WikiPage teardownPage = PageCrawlerImpl.getInheritedPage(type, page);
        if (teardownPage == null) {
            return "";
        }
        WikiPagePath path = teardownPage.getPageCrawler().getFullPath(teardownPage);
        return "!include -teardown ." + PathParser.render(path) + "\n";
    }
}
